// Clean-air index — record JAH-GGNS-AIRPURIFIER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"cadr": 200, "hepa_grade": 13, "noise_db": 30, "price_usd": 150};
var value = (m.cadr*m.hepa_grade/m.noise_db/m.price_usd*1000);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-AIRPURIFIER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-AIRPURIFIER-000001|' + value.toFixed(2) + ' clean-air index');

